struct Sequence { terms: Vec<Int> }

fn sequence_term(n: Int) -> Int {
    let mut terms = push(vec(), 1)
    for i in range(1, n) {
        terms = push(terms, terms.get(i - 1)? + terms.get(i - 2)?)
    }
    terms.get(n - 1)?
}

fn main() {
    print(sequence_term(10))
}

